changeSet.sql:
SET LOCAL lock_timeout='30s';
ALTER TABLE feedback DROP CONSTRAINT ck_feedback_stop_reason;
ALTER TABLE feedback ADD CONSTRAINT ck_feedback_stop_reason CHECK (stop_reason IS NULL OR stop_reason IN ('VOLUME_CAPPED','COMPOSER_WITHHELD','NOTHING_NEW','REPEATS_DELIVERED_NOTE','REACTED_DISAGREE','REACTED_NOT_APPLICABLE','CONVERSATION_EXPIRED','DELIVERY_UNCONFIRMED','ITEM_GONE','ITEM_CLOSED','ITEM_MERGED','ITEM_STATE_INELIGIBLE','ISSUE_SNAPSHOT_CHANGED','PUBLIC_SUBJECT_INELIGIBLE','NO_AI','DELIVERY_OFF','PERSON_SUPPRESSED','RECIPIENT_UNAVAILABLE','EMPTY_AFTER_SANITIZE','INSTANCE_SILENCED','FEEDBACK_OFF','WORKSPACE_DISABLED','WORKSPACE_DELIVERY_PAUSED','STALE_ROLLOUT_REVISION','OUTSIDE_CURRENT_SCOPE','APPROVAL_STALE','APPROVAL_NO_LONGER_ELIGIBLE','PRACTICE_REQUIRES_APPROVAL','BACKFILL_QUIET','RESULT_MARKED_INCORRECT','REVIEWED_VERSION_CHANGED','REVIEW_CANCELLED','EVIDENCE_NOT_PERMITTED','NO_EVIDENCE','UNCORROBORATED','PUBLIC_HISTORY_CHANGED','PUBLIC_DELIVERY_UNRESOLVED','NOT_COMPOSED'));
ALTER TABLE feedback_copy DROP CONSTRAINT ck_feedback_copy_stop_reason;
ALTER TABLE feedback_copy ADD CONSTRAINT ck_feedback_copy_stop_reason CHECK (stop_reason IS NULL OR stop_reason IN ('VOLUME_CAPPED','COMPOSER_WITHHELD','NOTHING_NEW','REPEATS_DELIVERED_NOTE','REACTED_DISAGREE','REACTED_NOT_APPLICABLE','CONVERSATION_EXPIRED','DELIVERY_UNCONFIRMED','ITEM_GONE','ITEM_CLOSED','ITEM_MERGED','ITEM_STATE_INELIGIBLE','ISSUE_SNAPSHOT_CHANGED','PUBLIC_SUBJECT_INELIGIBLE','NO_AI','DELIVERY_OFF','PERSON_SUPPRESSED','RECIPIENT_UNAVAILABLE','EMPTY_AFTER_SANITIZE','INSTANCE_SILENCED','FEEDBACK_OFF','WORKSPACE_DISABLED','WORKSPACE_DELIVERY_PAUSED','STALE_ROLLOUT_REVISION','OUTSIDE_CURRENT_SCOPE','APPROVAL_STALE','APPROVAL_NO_LONGER_ELIGIBLE','PRACTICE_REQUIRES_APPROVAL','BACKFILL_QUIET','RESULT_MARKED_INCORRECT','REVIEWED_VERSION_CHANGED','REVIEW_CANCELLED','EVIDENCE_NOT_PERMITTED','NO_EVIDENCE','UNCORROBORATED','PUBLIC_HISTORY_CHANGED','PUBLIC_DELIVERY_UNRESOLVED','NOT_COMPOSED'));

rollback.sql:
DO $restore$
BEGIN
 IF EXISTS (SELECT 1 FROM feedback WHERE stop_reason = 'NOT_COMPOSED') THEN RAISE EXCEPTION 'Cannot remove NOT_COMPOSED while feedback rows use it; use a forward fix or restore the matching backup.'; END IF;
 IF EXISTS (SELECT 1 FROM feedback_copy WHERE stop_reason = 'NOT_COMPOSED') THEN RAISE EXCEPTION 'Cannot remove NOT_COMPOSED while feedback_copy rows use it; use a forward fix or restore the matching backup.'; END IF;
 ALTER TABLE feedback DROP CONSTRAINT ck_feedback_stop_reason;
 ALTER TABLE feedback ADD CONSTRAINT ck_feedback_stop_reason CHECK (stop_reason IS NULL OR stop_reason IN ('VOLUME_CAPPED','COMPOSER_WITHHELD','NOTHING_NEW','REPEATS_DELIVERED_NOTE','REACTED_DISAGREE','REACTED_NOT_APPLICABLE','CONVERSATION_EXPIRED','DELIVERY_UNCONFIRMED','ITEM_GONE','ITEM_CLOSED','ITEM_MERGED','ITEM_STATE_INELIGIBLE','ISSUE_SNAPSHOT_CHANGED','PUBLIC_SUBJECT_INELIGIBLE','NO_AI','DELIVERY_OFF','PERSON_SUPPRESSED','RECIPIENT_UNAVAILABLE','EMPTY_AFTER_SANITIZE','INSTANCE_SILENCED','FEEDBACK_OFF','WORKSPACE_DISABLED','WORKSPACE_DELIVERY_PAUSED','STALE_ROLLOUT_REVISION','OUTSIDE_CURRENT_SCOPE','APPROVAL_STALE','APPROVAL_NO_LONGER_ELIGIBLE','PRACTICE_REQUIRES_APPROVAL','BACKFILL_QUIET','RESULT_MARKED_INCORRECT','REVIEWED_VERSION_CHANGED','REVIEW_CANCELLED','EVIDENCE_NOT_PERMITTED','NO_EVIDENCE','UNCORROBORATED','PUBLIC_HISTORY_CHANGED','PUBLIC_DELIVERY_UNRESOLVED'));
 ALTER TABLE feedback_copy DROP CONSTRAINT ck_feedback_copy_stop_reason;
 ALTER TABLE feedback_copy ADD CONSTRAINT ck_feedback_copy_stop_reason CHECK (stop_reason IS NULL OR stop_reason IN ('VOLUME_CAPPED','COMPOSER_WITHHELD','NOTHING_NEW','REPEATS_DELIVERED_NOTE','REACTED_DISAGREE','REACTED_NOT_APPLICABLE','CONVERSATION_EXPIRED','DELIVERY_UNCONFIRMED','ITEM_GONE','ITEM_CLOSED','ITEM_MERGED','ITEM_STATE_INELIGIBLE','ISSUE_SNAPSHOT_CHANGED','PUBLIC_SUBJECT_INELIGIBLE','NO_AI','DELIVERY_OFF','PERSON_SUPPRESSED','RECIPIENT_UNAVAILABLE','EMPTY_AFTER_SANITIZE','INSTANCE_SILENCED','FEEDBACK_OFF','WORKSPACE_DISABLED','WORKSPACE_DELIVERY_PAUSED','STALE_ROLLOUT_REVISION','OUTSIDE_CURRENT_SCOPE','APPROVAL_STALE','APPROVAL_NO_LONGER_ELIGIBLE','PRACTICE_REQUIRES_APPROVAL','BACKFILL_QUIET','RESULT_MARKED_INCORRECT','REVIEWED_VERSION_CHANGED','REVIEW_CANCELLED','EVIDENCE_NOT_PERMITTED','NO_EVIDENCE','UNCORROBORATED','PUBLIC_HISTORY_CHANGED','PUBLIC_DELIVERY_UNRESOLVED'));
END $restore$;
